+// Option 2: Use Bun's INSERT OR REPLACE with separate update (more portable)
+export function cachePut(db: Database, fp: string, provider: string, model: string, schemaHash: string, stateHash: string, answers: unknown): void {
+  const existing = db.query("SELECT hits FROM cache WHERE fingerprint = ?").get(fp);
+  db.run("DELETE FROM cache WHERE fingerprint = ?", [fp]);
+  db.run("INSERT INTO cache(fingerprint, provider, model, schema_hash, state_hash, answer_json, created_at, hits) VALUES (?,?,?,?,?,?,?, ?)",
